const uint32_t g_ordinal_name_count =
    (uint32_t)(sizeof g_ordinal_names / sizeof g_ordinal_names[0]);

/* The table is sorted by (dll, ordinal), so the lookup can stop early. */
static int on_dll_equal(const char *a, const char *b) {
    for (; *a && *b; a++, b++) {
        char ca = *a, cb = *b;
        if (ca >= 'A' && ca <= 'Z') ca = (char)(ca - 'A' + 'a');
        if (cb >= 'A' && cb <= 'Z') cb = (char)(cb - 'A' + 'a');
        if (ca != cb) return 0;
    }
    return *a == 0 && *b == 0;
}

const char *ordinal_name_lookup(const char *dll, uint32_t ordinal) {
    if (!dll || !ordinal) return NULL;
    for (uint32_t i = 0; i < g_ordinal_name_count; i++) {
        const OrdinalName *e = &g_ordinal_names[i];
        if (e->ordinal != ordinal) continue;
        if (on_dll_equal(e->dll, dll)) return e->name;
    }
    return NULL;
}
